```

Add the step variant and its handler:

```rust
/// A non-optional `Apply` whose driver is bound: its right operand sees each
/// input whose driver is certainly bound.
ApplyLeft(&'p GraphPattern, &'p ApplicationPolicy, Context, Written<'w>),

Step::ApplyLeft(right, policy, ctx, written) => {
    let left_bound = values.pop().expect("the driver is bound first");
    let outer = resolve(ctx, context, &arena);
    let mut right_context = outer.clone();
    for (input, driver) in &policy.inputs {
        if left_bound.contains(driver) || outer.contains(driver) {
            right_context.insert(input.clone());
        }
    }
    let mark = arena.len();
    arena.push(right_context);
    steps.push(Step::LateralRight(left_bound, mark));
    steps.push(Step::Enter(right, Context::Owned(mark), written));
}
```

With this change, only the optional `Apply` case reaches the `Exit` arm at Lines 2188-2197.
